import React, { useEffect, useRef, useState } from 'react';
import member from '../../../assets/member.png';
import President from '../../../assets/president.png';

const roles = [
  { title: 'President', name: 'Mr. XYZ Patel', img: President },
  { title: 'Vice-President', name: 'Mr. XYZ Patel', img: President },
  { title: 'Secretary', name: 'Mr. XYZ Patel', img: President },
  { title: 'Treasurer', name: 'Mr. XYZ Patel', img: member },
];

const members = [
  { title: 'Member', name: 'Mr. XYZabc Patel', img: member },
  { title: 'Member', name: 'Ms. ABCxyz Sharma', img: member },
  { title: 'Member', name: 'Mr. John Doe', img: member },
  { title: 'Member', name: 'Ms. Jane Smith', img: member },
  { title: 'Member', name: 'Mr. Alex Johnson', img: member },
  { title: 'Member', name: 'Ms. Emily Davis', img: member },
  { title: 'Member', name: 'Mr. Michael Lee', img: member },
  { title: 'Member', name: 'Ms. Sarah Brown', img: member },
];

const membersPerRole = 2;

export default function CommitteeTreeAnimated() {
  const containerRef = useRef(null);

  const presidentRef = useRef(null);
  const rolesRefs = useRef([]);
  rolesRefs.current = [];

  const membersRefs = useRef([]);
  membersRefs.current = [];

  const [lines, setLines] = useState([]);
  const [hoveredIndex, setHoveredIndex] = useState(null); // Track hovered card index

  const addRoleRef = (el) => {
    if (el && !rolesRefs.current.includes(el)) {
      rolesRefs.current.push(el);
    }
  };

  const addMemberRef = (el) => {
    if (el && !membersRefs.current.includes(el)) {
      membersRefs.current.push(el);
    }
  };

  useEffect(() => {
    function calculateLines() {
      if (!presidentRef.current || rolesRefs.current.length === 0 || membersRefs.current.length === 0)
        return;

      const containerRect = containerRef.current.getBoundingClientRect();

      // President → Roles
      const presidentRect = presidentRef.current.getBoundingClientRect();
      const presidentCenterX = presidentRect.left + presidentRect.width / 2 - containerRect.left;
      const presidentBottomY = presidentRect.bottom - containerRect.top;

      const presidentToRoles = rolesRefs.current.map((roleEl) => {
        const roleRect = roleEl.getBoundingClientRect();
        const roleCenterX = roleRect.left + roleRect.width / 2 - containerRect.left;
        const roleTopY = roleRect.top - containerRect.top;
        const controlPoint1 = { x: presidentCenterX, y: (presidentBottomY + roleTopY) / 2 };
        const controlPoint2 = { x: roleCenterX, y: (presidentBottomY + roleTopY) / 2 };
        return {
          startX: presidentCenterX,
          startY: presidentBottomY,
          endX: roleCenterX,
          endY: roleTopY,
          controlPoint1,
          controlPoint2,
          group: 'presidentToRoles',
        };
      });

      // Roles → Members
      const rolesToMembers = [];
      rolesRefs.current.forEach((roleEl, i) => {
        const roleRect = roleEl.getBoundingClientRect();
        const roleCenterX = roleRect.left + roleRect.width / 2 - containerRect.left;
        const roleBottomY = roleRect.bottom - containerRect.top;

        const startIdx = i * membersPerRole;
        const assignedMembers = membersRefs.current.slice(startIdx, startIdx + membersPerRole);

        assignedMembers.forEach((memberEl) => {
          if (!memberEl) return;
          const memberRect = memberEl.getBoundingClientRect();
          const memberCenterX = memberRect.left + memberRect.width / 2 - containerRect.left;
          const memberTopY = memberRect.top - containerRect.top;
          const controlPoint1 = { x: roleCenterX, y: (roleBottomY + memberTopY) / 2 };
          const controlPoint2 = { x: memberCenterX, y: (roleBottomY + memberTopY) / 2 };
          rolesToMembers.push({
            startX: roleCenterX,
            startY: roleBottomY,
            endX: memberCenterX,
            endY: memberTopY,
            controlPoint1,
            controlPoint2,
            group: `roleToMember-${i}`,
          });
        });
      });

      setLines([...presidentToRoles, ...rolesToMembers]);
    }

    calculateLines();
    window.addEventListener('resize', calculateLines);
    return () => window.removeEventListener('resize', calculateLines);
  }, []);

  // Handle hover highlighting
  // We link cards and lines by index:
  // Index 0 = President, roles start at 1, members after roles.
  // We store for each line which cards it connects to (indexes)
  // For simplicity, we highlight lines connected to hovered card (president, role or member).

  function isLineHighlighted(index, hoveredIdx) {
    if (hoveredIdx === null) return false;

    // Lines array: first roles.length-1 are President → Roles lines
    // then rest are Roles → Members lines.

    // President card index = 0
    if (hoveredIdx === 0) {
      // Highlight presidentToRoles lines
      return index < roles.length - 1;
    }

    // Roles indexes start at 1, members start after roles
    // lines for presidentToRoles: 0 to roles.length-2
    // lines for rolesToMembers: after roles.length-1

    if (hoveredIdx > 0 && hoveredIdx < roles.length) {
      // role index hovered (1 to roles.length-1)
      // Highlight:
      // 1) the line from president to this role (index = hoveredIdx-1)
      // 2) all lines from this role to members (rolesToMembers lines) for that role

      if (index === hoveredIdx - 1) return true; // President → this role

      // rolesToMembers lines start at roles.length-1
      // find lines connected to this role

      const roleIndex = hoveredIdx - 1;
      // Lines rolesToMembers indexed from roles.length-1
      const rolesToMembersStart = roles.length - 1;
      // Each role has membersPerRole lines in sequence

      if (
        index >= rolesToMembersStart + roleIndex * membersPerRole &&
        index < rolesToMembersStart + (roleIndex + 1) * membersPerRole
      )
        return true;
    }

    // Members start after roles, their index starts at roles.length
    if (hoveredIdx >= roles.length) {
      // Member hovered (index >= roles.length)
      // Highlight line connecting the member to role

      // Find which role this member belongs to:
      const memberIndex = hoveredIdx - roles.length;
      const roleIndex = Math.floor(memberIndex / membersPerRole);

      const rolesToMembersStart = roles.length - 1;
      const lineIndex = rolesToMembersStart + roleIndex * membersPerRole + (memberIndex % membersPerRole);

      return index === lineIndex;
    }

    return false;
  }

  return (
    <section
      ref={containerRef}
      id="tree-container"
      className="py-10 px-4 max-w-7xl mx-auto relative bg-white"
      style={{ minHeight: '700px' }}
    >
      <h2 className="text-2xl font-bold mb-12 text-center">Our Committee</h2>

      {/* President */}
      <div
        className="flex justify-center mb-20"
        onMouseEnter={() => setHoveredIndex(0)}
        onMouseLeave={() => setHoveredIndex(null)}
      >
        <NodeCard ref={presidentRef} {...roles[0]} isHovered={hoveredIndex === 0} />
      </div>

      {/* Roles */}
      <div className="flex justify-center space-x-20 mb-20">
        {roles.slice(1).map((role, i) => {
          const idx = i + 1; // role index start at 1
          return (
            <div
              key={i}
              onMouseEnter={() => setHoveredIndex(idx)}
              onMouseLeave={() => setHoveredIndex(null)}
            >
              <NodeCard ref={addRoleRef} {...role} isHovered={hoveredIndex === idx} />
            </div>
          );
        })}
      </div>

      {/* Members Grid */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-12 max-w-5xl mx-auto">
        {members.map((member, i) => {
          const idx = i + roles.length;
          return (
            <div
              key={i}
              onMouseEnter={() => setHoveredIndex(idx)}
              onMouseLeave={() => setHoveredIndex(null)}
            >
              <NodeCard ref={addMemberRef} {...member} isHovered={hoveredIndex === idx} />
            </div>
          );
        })}
      </div>

      {/* SVG connectors */}
      <svg
        className="absolute top-0 left-0 w-full h-full pointer-events-none"
        style={{ zIndex: 0, overflow: 'visible' }}
      >
        {lines.map(({ startX, startY, endX, endY, controlPoint1, controlPoint2 }, i) => {
          const highlighted = isLineHighlighted(i, hoveredIndex);
          return (
            <AnimatedPath
              key={i}
              d={`M${startX},${startY} C${controlPoint1.x},${controlPoint1.y} ${controlPoint2.x},${controlPoint2.y} ${endX},${endY}`}
              highlighted={highlighted}
            />
          );
        })}
      </svg>
    </section>
  );
}

// Forward ref component for card with highlight style
const NodeCard = React.forwardRef(({ img, title, name, isHovered }, ref) => (
  <div
    ref={ref}
    className={`text-center p-4 border rounded shadow w-36 mx-auto bg-white transition-shadow duration-300 ${
      isHovered ? 'border-yellow-500 shadow-lg' : 'border-gray-300'
    }`}
    style={{ minWidth: '140px' }}
  >
    <img
      src={img}
      alt={title}
      className="w-20 h-20 mx-auto rounded-full mb-3 object-cover"
      style={{ transition: 'transform 0.3s', transform: isHovered ? 'scale(1.1)' : 'scale(1)' }}
    />
    <div className="font-semibold text-md">{title}</div>
    <div className="text-xs text-gray-600">{name}</div>
  </div>
));

// Animated SVG path component
function AnimatedPath({ d, highlighted }) {
  const pathRef = useRef(null);
  const [length, setLength] = useState(0);

  useEffect(() => {
    if (pathRef.current) {
      setLength(pathRef.current.getTotalLength());
    }
  }, [d]);

  return (
    <path
      ref={pathRef}
      d={d}
      stroke={highlighted ? '#FACC15' : '#F48F0F'}
      strokeWidth={highlighted ? 4 : 3}
      fill="none"
      strokeLinecap="round"
      strokeDasharray={length}
      strokeDashoffset={length}
      style={{
        animation: 'drawLine 1s forwards',
        transition: 'stroke 0.3s, stroke-width 0.3s',
      }}
    />
  );
}

// Add this global style for the draw animation
// In your main CSS or inside a <style> tag somewhere:
/*
@keyframes drawLine {
  to {
    stroke-dashoffset: 0;
  }
}
*/
